import { expect, expectStatus, test } from "../../fixtures";

interface VendorBody {
  id: string;
  status: string;
}

interface DocumentBody {
  id: string;
  status: string;
}

interface ExtractionBody {
  id: string;
  status: string;
}

interface ReviewQueueItemBody {
  vendor_id: string;
  extractions: ExtractionBody[];
}

interface AuditBody {
  items: { action: string }[];
}

const DOCUMENT_KINDS = ["w9", "insurance_certificate", "contract"] as const;

async function waitForDocumentSettled(
  ctx: Parameters<typeof expectStatus>[0] extends never ? never : import("../../fixtures").APIRequestContext,
  documentId: string,
): Promise<string> {
  for (let attempt = 0; attempt < 60; attempt++) {
    const body = await expectStatus<DocumentBody>(await ctx.get(`/api/documents/${documentId}`), 200);
    if (body.status !== "processing") {
      return body.status;
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} still processing after timeout`);
}

test.describe("review vendors", () => {
  test(
    "approving every extraction approves the vendor",
    { tag: "@REV-05" },
    async ({ apiAs }) => {
      // Arrange: a unique vendor name and contact so parallel runs don't collide.
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");

      const created = await expectStatus<VendorBody>(
        await member.post("/api/vendors", {
          data: {
            name: `REV-05 Vendor ${suffix}`,
            category: "services",
            contact_email: `rev05-${suffix}@example.test`,
          },
        }),
        201,
      );
      const vendorId = created.id;

      // Arrange: upload one document per kind and wait for extraction to finish.
      for (const kind of DOCUMENT_KINDS) {
        const upload = await expectStatus<DocumentBody>(
          await member.post(`/api/vendors/${vendorId}/documents`, {
            multipart: {
              kind,
              file: {
                name: `${kind}-${suffix}.pdf`,
                mimeType: "application/pdf",
                buffer: Buffer.from("%PDF-1.4 REV-05 sample document"),
              },
            },
          }),
          201,
        );
        const settled = await waitForDocumentSettled(member, upload.id);
        expect(settled).toBe("extracted");
      }

      // Arrange: submit the vendor so it is in review with three pending extractions.
      const submitted = await expectStatus<VendorBody>(
        await member.post(`/api/vendors/${vendorId}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      const queue = await expectStatus<ReviewQueueItemBody[]>(
        await reviewer.get("/api/review-queue"),
        200,
      );
      const item = queue.find((entry) => entry.vendor_id === vendorId);
      expect(item).toBeDefined();
      expect(item!.extractions).toHaveLength(3);
      for (const extraction of item!.extractions) {
        expect(extraction.status).toBe("pending_review");
      }

      // Act: approve all three extractions.
      for (const extraction of item!.extractions) {
        const decided = await expectStatus<ExtractionBody>(
          await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
            data: { decision: "approve" },
          }),
          200,
        );
        expect(decided.status).toBe("approved");
      }

      // Assert: the vendor is approved.
      const vendor = await expectStatus<VendorBody>(
        await reviewer.get(`/api/vendors/${vendorId}`),
        200,
      );
      expect(vendor.status).toBe("approved");

      // Assert: an audit event "vendor.approved" is recorded.
      const audit = await expectStatus<AuditBody>(
        await reviewer.get(`/api/vendors/${vendorId}/audit`),
        200,
      );
      expect(audit.items.map((event) => event.action)).toContain("vendor.approved");
    },
  );
});
